#include <iostream>
#include <cctype>

void test_char(char ch) {
    auto uc = static_cast<unsigned char>(ch);
    std::cout << "Testing '" << ch << "': "
              << "digit=" << (std::isdigit(uc) ? "true " : "false ")
              << "alpha=" << (std::isalpha(uc) ? "true " : "false ")
              << "alnum=" << (std::isalnum(uc) ? "true " : "false ")
              << "xdigit=" << (std::isxdigit(uc) ? "true" : "false")
              << "\n";
}

int main() {
    test_char('8');
    test_char('A');
    test_char('f');
    test_char('&');
    return 0;
}

#include <iostream>
#include <cctype>

int main() {
    char chars[] = {'p', 'P', '5', '!', 'u', '7', '$', 'L'};
    for (char c : chars) {
        auto uc = static_cast<unsigned char>(c);
        char lower_c = static_cast<char>(std::tolower(uc));
        char upper_c = static_cast<char>(std::toupper(uc));
        std::cout << "Char '" << c << "': "
                  << (std::islower(uc) ? "is_lower " : "not_lower ")
                  << (std::isupper(uc) ? "is_upper " : "not_upper ")
                  << "to_upper=" << upper_c << " "
                  << "to_lower=" << lower_c << "\n";
    }
    return 0;
}

#include <iostream>
#include <cctype>

void evaluate(const char* name, char ch) {
    auto uc = static_cast<unsigned char>(ch);
    std::cout << name << ": "
              << "isspace=" << (std::isspace(uc) ? 1 : 0) << " "
              << "iscntrl=" << (std::iscntrl(uc) ? 1 : 0) << " "
              << "ispunct=" << (std::ispunct(uc) ? 1 : 0) << " "
              << "isprint=" << (std::isprint(uc) ? 1 : 0) << " "
              << "isgraph=" << (std::isgraph(uc) ? 1 : 0) << "\n";
}

int main() {
    evaluate("Newline \\n", '\n');
    evaluate("Space ' '   ", ' ');
    evaluate("Semi-colon ;", ';');
    evaluate("Letter 'Q'  ", 'Q');
    return 0;
}
